alter table news add column if not exists legacy boolean not null default false;
alter table projects add column if not exists legacy boolean not null default false;
alter table partners add column if not exists legacy boolean not null default false;
alter table team add column if not exists legacy boolean not null default false;

insert into news(title,category,body,image_url,images,legacy,published,created_at)
select * from (values
($v$Impact Leadership Award Finalist$v$,$v$Industry Recognition$v$,$v$Smart Vision proudly reached the final stage of the Impact Leadership Award 2026, competing with the largest engineering organizations in Egypt. The company continues to set new benchmarks in innovation and excellence.$v$,$v$New folder/ntitled design.jpg$v$,array[$v$New folder/ntitled design.jpg$v$],true,true,timestamptz '2026-02-02 12:00+00'),
($v$Impact Leadership Award Finalist$v$,$v$Corporate Partnership$v$,$v$Impact Leadership Award Finalist — Smart Vision proudly reached the final stage of the Impact Leadership Award 2025, competing with the largest engineering organizations in Egypt. The company continues to set new benchmarks in innovation and excellence.$v$,$v$0025.jpeg$v$,array[$v$0025.jpeg$v$],true,true,timestamptz '2025-09-15 12:00+00'),
($v$Smart Vision Reaches Final of the Impact Leadership Award at Big 5 Egypt$v$,$v$Project Milestone$v$,$v$Smart Vision for Engineering Consultancy has achieved a remarkable milestone by reaching the finals of the prestigious Impact Leadership Award at Big 5 Egypt 2025, one of the region's leading events in the construction and engineering sector. Competing alongside major industry names such as the Arab Contractors and the Egyptian Consultants Group, Smart Vision stands out as a growing company with a strong strategic vision and measurable impact.
Following this recognition, the company has been selected to represent Egypt at Big 5 Global in Dubai in November 2025, marking a significant step toward international expansion and positioning among the top players in sustainable construction and advanced engineering.
Eng. Mohamed Osama Hassan, Chairman of Smart Vision, stated: "Our journey to the finals and our qualification for Big 5 Global reflect our belief that small companies can achieve great things when they combine vision, quality, and commitment to their clients."$v$,$v$WhatsApp Image 2026-05-25 at 2.32.34 AM.jpeg$v$,array[$v$WhatsApp Image 2026-05-25 at 2.32.34 AM.jpeg$v$],true,true,timestamptz '2025-10-24 12:00+00')
) as t(title,category,body,image_url,images,legacy,published,created_at)
where not exists (select 1 from news where legacy);

