insert into team(name,role,bio,photo_url,tier,sort,legacy,published)
select * from (values
($v$Mohamed Osama Hassaan$v$,$v$Founder,Chairman &Ceo$v$,$v$Has been a driving force behind the growth of SMART VISION. He serves as Chairman & CEO of the Board of Directors and has guided the company from its first projects in 2004 into a leading consultant player in Egypt. Known from an early age amongst his colleagues to possess a strong business sense, also he is the founder and CEO of O Consult (General Consultancy Company). Beyond his corporate role, Osama serves as a mentor to many aspiring professionals, actively contributes community initiatives, and is frequently commissioned to author books on self-development and leadership.$v$,$v$WhatsApp Image 2026-05-24 at 8.21.51 PM.jpeg$v$,$v$executive$v$,0,true,true),
($v$Arch. Ahmed Amin$v$,$v$Co-Founder & CFO$v$,$v$As CFO, he has guided the company from its first projects in 2004 into a leading consultant player in Egypt. Arch. Amin occupied managerial positions handling a diversity of residential and commercial projects. Amin holds a Bachelor of Architecture from faculty of Fine Arts, and Management Diploma from Ain Shams University.$v$,$v$WhatsApp Image 2026-05-25 at 12.25.23 AM.jpeg$v$,$v$executive$v$,1,true,true),
($v$Michel Mounir$v$,$v$Head of MEP$v$,$v$Leading SMART VISION's mechanical, electrical and plumbing projects with precision and innovation.$v$,$v$unknow.jpg$v$,$v$member$v$,2,true,true),
($v$Heba Abd AlHamid$v$,$v$Head of Cost Control$v$,$v$Driving SMART VISION's projects profitability through strategic budgeting and cost optimization.$v$,$v$female-profile.jpg$v$,$v$member$v$,3,true,true),
($v$Eslam Fares$v$,$v$Structural Team Leader$v$,$v$Guiding SMART VISION's structural team to deliver innovative, code-compliant, and high-impact designs with precision and collaboration.$v$,$v$WhatsApp Image 2026-05-26 at 5.27.33 PM.jpeg$v$,$v$member$v$,4,true,true),
($v$Malak Ibrahim$v$,$v$Project Coordinator$v$,$v$Coordinate all projects' trades between all team members for SMART VISION's Projects.$v$,$v$female-profile.jpg$v$,$v$member$v$,5,true,true),
($v$Ahmed Ayman$v$,$v$Site Supervision Eng.$v$,$v$Site Supervision Engineer responsible for on-site quality and execution oversight.$v$,$v$unknow.jpg$v$,$v$member$v$,6,true,true)
) as t(name,role,bio,photo_url,tier,sort,legacy,published)
